import{_ as a,o as t,c as n,a6 as e}from"./chunks/framework.BrkgobfX.js";const b=JSON.parse('{"title":"权重格式","description":"safetensors 与 pickle 的安全差异、GGUF 是什么、以及各种量化格式怎么选。","frontmatter":{"title":"权重格式","description":"safetensors 与 pickle 的安全差异、GGUF 是什么、以及各种量化格式怎么选。","source":"https://daiw.org/manual/huggingface/weight-formats"},"headers":[],"relativePath":"manual/llm/huggingface/weight-formats.md","filePath":"manual/llm/huggingface/weight-formats.md"}'),i={name:"manual/llm/huggingface/weight-formats.md"};function l(r,s,o,p,d,c){return t(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="权重格式" tabindex="-1">权重格式 <a class="header-anchor" href="#权重格式" aria-label="Permalink to &quot;权重格式&quot;">​</a></h1><blockquote><p>safetensors 与 pickle 的安全差异、GGUF 是什么、以及各种量化格式怎么选。</p></blockquote><p>同一个模型在 Hub 上常有四五种格式。选错了要么下白工，要么跑不起来。这一篇把它们的关系理清。</p><h2 id="两个正交的维度" tabindex="-1">两个正交的维度 <a class="header-anchor" href="#两个正交的维度" aria-label="Permalink to &quot;两个正交的维度&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          序列化格式                   数值精度</span></span>
<span class="line"><span>   ┌──────────────────────┐   ×   ┌────────────────────┐</span></span>
<span class="line"><span>   │ safetensors / .bin   │       │ fp32 / bf16 / fp16 │</span></span>
<span class="line"><span>   │ GGUF / ONNX          │       │ fp8 / int8 / int4  │</span></span>
<span class="line"><span>   └──────────────────────┘       └────────────────────┘</span></span>
<span class="line"><span>        “文件怎么存”                “数字有多精细”</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>这两件事经常被混为一谈</strong>。“GGUF”是格式，“Q4_K_M”是量化方案，一个 GGUF 文件里可以是 fp16 也可以是 int4。</p><h2 id="序列化格式" tabindex="-1">序列化格式 <a class="header-anchor" href="#序列化格式" aria-label="Permalink to &quot;序列化格式&quot;">​</a></h2><h3 id="safetensors-——-默认选它" tabindex="-1">safetensors —— 默认选它 <a class="header-anchor" href="#safetensors-——-默认选它" aria-label="Permalink to &quot;safetensors —— 默认选它&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[8 字节 header 长度][JSON header][紧密排列的张量数据]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>设计目标只有两个：<strong>安全</strong>与<strong>快</strong>。</p><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td><strong>不执行代码</strong></td><td>纯数据格式，加载时不可能运行任何东西</td></tr><tr><td><strong>零拷贝加载</strong></td><td>可以 mmap，大模型加载明显更快</td></tr><tr><td><strong>可部分读取</strong></td><td>能只读某几个张量而不加载整个文件</td></tr></tbody></table><h3 id="pytorch-model-bin-——-能避就避" tabindex="-1">pytorch_model.bin —— 能避就避 <a class="header-anchor" href="#pytorch-model-bin-——-能避就避" aria-label="Permalink to &quot;pytorch_model.bin —— 能避就避&quot;">​</a></h3><p>它是 Python <code>pickle</code>。<strong>pickle 在反序列化时会执行代码</strong>——这不是 bug，是设计。</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 一个恶意的 .bin 文件可以在你 load 的瞬间做任何事</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">torch.load(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;innocent_looking.bin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 可能已经中招</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>这不是理论风险。</strong> Hub 上出现过投毒的 pickle 权重，HuggingFace 因此专门做了扫描（模型页会显示 pickle 安全扫描结果）。</p><p>实践纪律：</p><ol><li><strong>有 safetensors 就绝不下 <code>.bin</code>。</strong></li><li>万不得已要加载 <code>.bin</code>，用 <code>torch.load(..., weights_only=True)</code>（PyTorch 2.6+ 已默认如此）。</li><li>来源不明的仓库，<strong>别碰 pickle 权重</strong>。</li></ol><p>这也是 safetensors 被造出来的全部原因。</p></div><h3 id="gguf-——-llama-cpp-生态" tabindex="-1">GGUF —— llama.cpp 生态 <a class="header-anchor" href="#gguf-——-llama-cpp-生态" aria-label="Permalink to &quot;GGUF —— llama.cpp 生态&quot;">​</a></h3><p>单文件、自包含（权重 + tokenizer + 元数据全在一个文件里），为 <strong>CPU / Apple Silicon 推理</strong>优化。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Qwen3-8B-Q4_K_M.gguf     ← 一个文件，拷走就能跑</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>特点：</p><ul><li><strong>一个文件搞定</strong>，不用管分片索引和 tokenizer 配置。</li><li><strong>CPU 上快</strong>，支持部分层卸载到 GPU（<code>-ngl</code>）。</li><li>通常由社区转换，常见发布者：<code>unsloth</code>、<code>bartowski</code>、<code>Qwen</code> 官方等。</li><li><strong>训练用不了</strong>——它是纯推理格式。</li></ul><p>用法见 <a href="/Front2Full/manual/llm/huggingface/gguf-llamacpp-ollama">GGUF 路线</a>。</p><h3 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>用途</th></tr></thead><tbody><tr><td><strong>ONNX</strong></td><td>跨框架部署、ONNX Runtime、移动端</td></tr><tr><td><strong>MLX</strong></td><td>Apple Silicon 专用（<code>mlx-community/</code> 下有很多）</td></tr><tr><td><strong>TensorRT-LLM engine</strong></td><td>NVIDIA 极致推理性能，需自己编译</td></tr></tbody></table><h2 id="数值精度" tabindex="-1">数值精度 <a class="header-anchor" href="#数值精度" aria-label="Permalink to &quot;数值精度&quot;">​</a></h2><h3 id="未量化" tabindex="-1">未量化 <a class="header-anchor" href="#未量化" aria-label="Permalink to &quot;未量化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>dtype</th><th>字节/参数</th><th>说明</th></tr></thead><tbody><tr><td><code>float32</code></td><td>4</td><td>训练主权重精度，推理很少用</td></tr><tr><td><code>float16</code></td><td>2</td><td>老卡（Turing 之前）用它</td></tr><tr><td><strong><code>bfloat16</code></strong></td><td>2</td><td><strong>现在的事实标准</strong>，动态范围大，不易溢出</td></tr></tbody></table><p><strong>fp16 与 bf16 都是 2 字节，但 bf16 更稳</strong>——它牺牲精度换指数范围，训练时不容易出 NaN。Ampere（RTX 30 系）及以后的卡都支持。</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># transformers v5 推荐用 dtype=&quot;auto&quot;（旧名 torch_dtype=&quot;auto&quot; 仍兼容）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AutoModelForCausalLM.from_pretrained(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org/model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">dtype</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><code>&quot;auto&quot;</code> 会读 <code>config.json</code> 里的原始精度配置，<strong>这是最省心的写法</strong>——比自己写死 <code>torch.float16</code> 好。</p><h3 id="量化" tabindex="-1">量化 <a class="header-anchor" href="#量化" aria-label="Permalink to &quot;量化&quot;">​</a></h3><p>把权重压到更少的位数，用精度换显存。</p><table tabindex="0"><thead><tr><th>方案</th><th>位数</th><th>特点</th></tr></thead><tbody><tr><td><strong>bitsandbytes NF4</strong></td><td>4</td><td><code>transformers</code> 里加两行就能用，<strong>微调（QLoRA）必备</strong></td></tr><tr><td><strong>GPTQ</strong></td><td>4 / 8</td><td>需要校准数据，推理快</td></tr><tr><td><strong>AWQ</strong></td><td>4</td><td>激活感知，同位数下质量常优于 GPTQ</td></tr><tr><td><strong>FP8 / MXFP4（原生量化）</strong></td><td>8 / 4</td><td>2025–2026 大模型常用，需 Ada/Hopper（FP8）或 Blackwell（FP4/MXFP4）硬件配合 vLLM/SGLang</td></tr><tr><td><strong>GGUF Q4_K_M 等</strong></td><td>混合</td><td>llama.cpp 生态，<strong>CPU 友好</strong></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>GGUF 的量化命名怎么读：</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q4_K_M</span></span>
<span class="line"><span>│ │ └── 尺寸档：S（小）/ M（中）/ L（大）</span></span>
<span class="line"><span>│ └──── K-quant 方法（比老的 Q4_0 质量好）</span></span>
<span class="line"><span>└────── 4 bit</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>不知道选哪个就选 <code>Q4_K_M</code></strong>——它是体积与质量平衡得极好的一档，社区默认推荐。</p><p>显存充裕想要更好质量：<code>Q5_K_M</code> 或 <code>Q6_K</code>。极度受限：<code>Q3_K_M</code> 或带重要性矩阵校准的 <code>IQ4_XS</code>，但更低位数质量下降开始明显。<strong><code>Q2</code> 系一般不值得</strong>——省下的显存不多，质量损失很大。</p></div><h3 id="量化损失有多大" tabindex="-1">量化损失有多大 <a class="header-anchor" href="#量化损失有多大" aria-label="Permalink to &quot;量化损失有多大&quot;">​</a></h3><p>粗略经验：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bf16  →  Q8 / FP8  几乎无损</span></span>
<span class="line"><span>      →  Q6_K      损失很小</span></span>
<span class="line"><span>      →  Q5_K_M    轻微</span></span>
<span class="line"><span>      →  Q4_K_M    可察觉但通常可接受   ← 甜点</span></span>
<span class="line"><span>      →  Q3_K      明显</span></span>
<span class="line"><span>      →  Q2_K      严重</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>模型越大，量化越抗损。</strong> 70B 的 Q4 常常比 8B 的 bf16 更好用——<strong>同样的显存下，优先选“更大的模型 + 更狠的量化”</strong>，这是社区反复验证过的经验。</p><h2 id="怎么选" tabindex="-1">怎么选 <a class="header-anchor" href="#怎么选" aria-label="Permalink to &quot;怎么选&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的目标是？</span></span>
<span class="line"><span>├── 在 GPU 上跑推理</span></span>
<span class="line"><span>│   ├── 显存够 → safetensors + bf16（或 Hopper/Blackwell 上用 FP8）</span></span>
<span class="line"><span>│   └── 显存紧 → safetensors + AWQ/GPTQ 4bit，或 GGUF</span></span>
<span class="line"><span>├── 在 CPU / Mac 上跑 → GGUF（Q4_K_M 起步） or MLX（Mac）</span></span>
<span class="line"><span>├── 要微调 → safetensors + bf16（QLoRA 时配 bitsandbytes 4bit）</span></span>
<span class="line"><span>└── 要部署成服务、追吞吐 → safetensors + AWQ/FP8，配 vLLM</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>GGUF 不能用来训练。</strong> 想微调就必须下原始的 safetensors 权重——见到有人下了 GGUF 再问“怎么微调”，答案是重新下。</p><p>反过来，微调完想在 CPU 上跑，需要<strong>合并 LoRA 后转换成 GGUF</strong>（llama.cpp 仓库里有 <code>convert_hf_to_gguf.py</code>）。</p></div><h2 id="一个实际的例子" tabindex="-1">一个实际的例子 <a class="header-anchor" href="#一个实际的例子" aria-label="Permalink to &quot;一个实际的例子&quot;">​</a></h2><p>同一个 8B 模型，四种选择的对比：</p><table tabindex="0"><thead><tr><th>选择</th><th>体积</th><th>能跑的硬件</th><th>质量</th></tr></thead><tbody><tr><td>safetensors bf16</td><td>~16 GB</td><td>24 G 显卡</td><td>基准</td></tr><tr><td>AWQ 4bit</td><td>~5.5 GB</td><td>8 G 显卡</td><td>轻微下降</td></tr><tr><td>GGUF Q4_K_M</td><td>~5 GB</td><td><strong>纯 CPU 也行</strong>（慢）</td><td>轻微下降</td></tr><tr><td>GGUF Q8_0</td><td>~8.5 GB</td><td>CPU / 小显卡</td><td>几乎无损</td></tr></tbody></table><p><strong>8 G 显卡跑 8B 模型，靠的就是量化。</strong> 具体选型见<a href="/Front2Full/manual/llm/huggingface/choose-by-vram">按显存选模型</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>格式与精度是两个维度</strong>，别混为一谈。</li><li><strong>safetensors 优先</strong>——pickle（<code>.bin</code>）加载时会执行代码，是真实风险。</li><li><strong>GGUF 是单文件推理格式</strong>，CPU/Mac 首选，<strong>不能训练</strong>。</li><li>dtype 写 <strong><code>dtype=&quot;auto&quot;</code></strong>（或兼容写法 <code>torch_dtype=&quot;auto&quot;</code>）最省心；bf16 是现在的标准。</li><li>量化不知道选什么就 <strong><code>Q4_K_M</code></strong>。</li><li><strong>同等显存下，大模型 + 重量化 通常优于 小模型 + 轻量化</strong>。</li></ul><p>下一篇：<a href="/Front2Full/manual/llm/huggingface/cli-and-auth">命令行与登录</a>。</p>`,47)])])}const g=a(i,[["render",l]]);export{b as __pageData,g as default};
